import{_ as a,o as e,c as n,a3 as i}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"Explaining, Predicting, and Applying the 4n, 1s Stall (Output Lag)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/explaining-predicting-and-applying-the-4n-1s-stall"}]],"lang":"en-US","translationSource":{"title":"4n卡1s\\\\(输出迟滞\\\\)现象的解释预测与应用","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=fpMndghZj3dpXscC34t8jt","scope":"page"}},"headers":[],"relativePath":"explaining-predicting-and-applying-the-4n-1s-stall.md","filePath":"logistics/src/page-fpMndghZj3dpXscC34t8jt.md","lastUpdated":null}'),d={name:"explaining-predicting-and-applying-the-4n-1s-stall.md"};function s(l,t,o,p,r,c){return e(),n("div",null,[...t[0]||(t[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="_4n卡1s-输出迟滞-现象的解释预测与应用" aria-hidden="true"></span><h1 id="explaining-predicting-and-applying-the-4n-1s-stall-output-lag" tabindex="-1">Explaining, Predicting, and Applying the 4n, 1s Stall (Output Lag) <a class="header-anchor" href="#explaining-predicting-and-applying-the-4n-1s-stall-output-lag" aria-label="Permalink to &quot;Explaining, Predicting, and Applying the 4n, 1s Stall (Output Lag)&quot;">​</a></h1><blockquote><p>Source page ID: <code>fpMndghZj3dpXscC34t8jt</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=fpMndghZj3dpXscC34t8jt" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-ogOroMAolpZ3oShXTLhIbX"></span></p><span class="logistics-source-anchor" id="应用" aria-hidden="true"></span><h2 id="applications" tabindex="-1">Applications: <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;Applications:&quot;">​</a></h2><p>A belt&#39;s 4n, 1s stall ultimately gives 2s stalled per 8n, equivalent to 1 item, hence output 8n/(8n+1). The representative case n＝3 gives 24/25. Quick-reference results:</p><table tabindex="0"><thead><tr><th>1</th><th>8/9</th></tr></thead><tbody><tr><td>2</td><td>16/17</td></tr><tr><td>3</td><td>24/25</td></tr><tr><td>4</td><td>32/33</td></tr><tr><td>5</td><td>40/41</td></tr><tr><td>6</td><td>48/49</td></tr><tr><td>7</td><td>56/57</td></tr><tr><td>8</td><td>64/65</td></tr><tr><td>9</td><td>72/73</td></tr></tbody></table><p>Pipes flow 4 times faster, giving a 0.5s stall per 2n = 1 fluid unit, output 2n/(2n+1). Theoretically every odd denominator above 1 up to 2*80+1=161 is possible.</p><p><span id="source-block-QwOGl5cUSHHmcEN43Acq41"></span></p><span class="logistics-source-anchor" id="常用实现结构" aria-hidden="true"></span><h4 id="common-implementation" tabindex="-1">Common Implementation: <a class="header-anchor" href="#common-implementation" aria-label="Permalink to &quot;Common Implementation:&quot;">​</a></h4><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-3e48174d964e16f1.q90-b8448fab1a445965.webp" alt="Image"></td></tr></tbody></table><p>Place the outputless Belt Bridge later than the downstream stash.</p><p><span id="source-block-e8EeFYsYFoS9sHQsgKByzz"></span></p><span class="logistics-source-anchor" id="解释预测" aria-hidden="true"></span><h2 id="explanation-and-prediction" tabindex="-1">Explanation and Prediction <a class="header-anchor" href="#explanation-and-prediction" aria-label="Permalink to &quot;Explanation and Prediction&quot;">​</a></h2><p>See <a href="/endfield-skydoc/introduction-to-analyzing-endfield-logistics-bugs">Introduction to Analyzing Endfield Logistics Bugs</a>.</p></div>',1)])])}const u=a(d,[["render",s]]);export{g as __pageData,u as default};
